contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address caller) public {
        require(caller != address(0), "caller must be nonzero");
        bool isApprovedBefore = c.approvedToLog(caller); if (__ESBMC_reverted()) return;
        bool returned = c.logFunded(); if (__ESBMC_reverted()) return;
        bool isApprovedAfter = c.approvedToLog(caller); if (__ESBMC_reverted()) return;
        assert(returned == isApprovedBefore && isApprovedAfter == isApprovedBefore);
    }
}

